// Extract email fields from Gmail Trigger output
const item = $input.first().json;

const subject = item.subject || item.headers?.subject || '';

// Gmail returns 'from' as object {address, name}, array, or string
const fromField = item.from;
let from_name = '';
let from_email = '';

if (Array.isArray(fromField)) {
  from_name = fromField[0]?.name || '';
  from_email = fromField[0]?.address || '';
} else if (typeof fromField === 'object' && fromField !== null) {
  from_name = fromField.name || '';
  from_email = fromField.address || '';
} else if (typeof fromField === 'string') {
  const match = fromField.match(/<(.+?)>/);
  if (match) {
    from_email = match[1];
    from_name = fromField.replace(/<.+?>/, '').replace(/"/g, '').trim();
  } else {
    from_email = fromField.trim();
  }
}

// Get body and sanitize for JSON safety
let body = item.textPlain || item.text || item.snippet || item.body || '';
if (!body && item.html) { body = item.html.replace(/<[^>]*>/g, ' '); }
body = body.replace(/\r\n/g, ' ').replace(/\n/g, ' ').replace(/\r/g, ' ').replace(/\t/g, ' ');
body = body.replace(/[\x00-\x1F\x7F]/g, '');
body = body.replace(/\s+/g, ' ').trim();

const received_at = item.date || item.internalDate || new Date().toISOString();

return [{ json: { subject, from_name, from_email, body, received_at } }];

const item = $input.first().json;

let raw =
  item.choices?.[0]?.message?.content ??
  item.data?.choices?.[0]?.message?.content ??
  '';

if (typeof raw !== 'string') {
  return [{ json: { path: 'k', parse_error: true } }];
}

raw = raw.trim().toLowerCase().replace(/[^a-z]/g, '');

const validPaths = ['k', 'consumer', 'retail'];
const path = validPaths.includes(raw) ? raw : 'k';

let emailData = {};
try { emailData = $('Parse Original Body').first()?.json || {}; }
catch(e) { emailData = {}; }

return [{ json: {
  subject:     emailData.subject     || '',
  from_name:   emailData.from_name   || '',
  from_email:  emailData.from_email  || '',
  body:        emailData.body        || '',
  received_at: emailData.received_at || '',
  path
} }];

const item = $input.first().json;
let raw = item.choices?.[0]?.message?.content ?? item.data?.choices?.[0]?.message?.content ?? '';
if (typeof raw !== 'string') { return [{ json: { parse_error: true, raw_output: raw } }]; }
raw = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/, '');
let parsed;
try { parsed = JSON.parse(raw); }
catch (e) { return [{ json: { parse_error: true, raw_output: raw } }]; }

const path = $('Parse Path').first()?.json?.path || 'k';
const emailData = $('Parse Original Body').first()?.json || {};

// stated_revenue_aud — must be integer or null, never empty string
// the trigger does numeric comparisons so it needs a real number or null
const rawRevenue = parsed.stated_revenue_aud;
const stated_revenue_aud = (rawRevenue !== '' && rawRevenue !== null && rawRevenue !== undefined && !isNaN(Number(rawRevenue)))
  ? parseInt(rawRevenue, 10)
  : null;

// booleans — LLM sometimes returns strings 'true'/'false', normalise to real booleans
const price_shopping    = parsed.price_shopping === true    || parsed.price_shopping    === 'true';
const cannot_influence  = parsed.cannot_influence === true  || parsed.cannot_influence  === 'true'
                       || parsed.cannot_influence_decision === true || parsed.cannot_influence_decision === 'true';

// fields_inferred — DO NOT cap at 2 anymore, the v5 trigger uses the real value
// for confidence calculation. Let the trigger decide confidence level.
const fields_inferred = typeof parsed.fields_inferred === 'number'
  ? Math.min(parsed.fields_inferred, 6)
  : 0;

return [{ json: {
  path,
  subject:                emailData.subject             || '',
  from_name:              emailData.from_name           || '',
  from_email:             emailData.from_email          || '',
  detected_language:      emailData.detected_language   || 'en',
  original_body:          emailData.original_body       || '',
  sender_name:            parsed.sender_name            ?? '',
  sender_email:           parsed.sender_email           ?? '',
  company_name:           parsed.company_name           ?? '',
  team_size:              parsed.team_size              ?? '',
  stated_revenue_aud,
  sector_fit_signal:      parsed.sector_fit_signal      ?? '',
  sector_fit_confidence:  parsed.sector_fit_confidence  ?? 'inferred',
  exec_sponsor_signal:    parsed.exec_sponsor_signal    ?? '',
  ai_appetite_signal:     parsed.ai_appetite_signal     ?? '',
  budget_timeline_signal: parsed.budget_timeline_signal ?? '',
  relationship_signal:    parsed.relationship_signal    ?? '',
  budget_signal:          parsed.budget_signal          ?? '',
  timeline_signal:        parsed.timeline_signal        ?? '',
  price_shopping,
  cannot_influence,
  fields_inferred
} }];

const item = $input.first().json;
let raw = item.choices?.[0]?.message?.content ?? '';
if (typeof raw !== 'string') { return [{ json: { parse_error: true, raw_output: raw } }]; }
raw = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/, '');
let parsed;
try { parsed = JSON.parse(raw); }
catch (e) { return [{ json: { parse_error: true, raw_output: raw } }]; }

const emailData = $('Parse Original Body').first()?.json || {};

// ── SOURCE CHANNEL ────────────────────────────────────────────
// Now decided by the LLM (per V5 doc §2.4). Code no longer infers
// from the body — just validate the key, fall back to cold_unknown.
const validChannels = ['paid_ad_click', 'direct_message', 'organic_comment', 'cold_unknown'];
const source_channel_signal = validChannels.includes(parsed.source_channel_signal)
  ? parsed.source_channel_signal
  : 'cold_unknown';

// ── CONTACT COMPLETENESS ──────────────────────────────────────
const hasName  = !!(parsed.sender_name  || emailData.from_name);
const hasEmail = !!(parsed.sender_email || emailData.from_email);
const hasPhone = !!(parsed.sender_phone);
const contactCount = [hasName, hasEmail, hasPhone].filter(Boolean).length;
const contact_completeness_signal =
  contactCount >= 3 ? 'full_contact'  :
  contactCount === 2 ? 'two_of_three' :
  contactCount === 1 ? 'minimal'      :
  'no_contact';

// ── FIELDS INFERRED ───────────────────────────────────────────
const fields_inferred = [
  (!parsed.purchase_intent_signal || parsed.purchase_intent_signal === '') ? 1 : 0,
  (!parsed.extracted_city || parsed.extracted_city === '')                  ? 1 : 0,
  (!parsed.product_fit_signal || parsed.product_fit_signal === '')          ? 1 : 0,
  (!parsed.buyer_urgency_signal || parsed.buyer_urgency_signal === '')      ? 1 : 0,
].reduce((a, b) => a + b, 0);
// Note: source_channel and contact_completeness are set/validated here,
// so they are never counted as inferred.

// ── BOOLEANS ─────────────────────────────────────────────────
const designer_flag  = parsed.designer_flag  === true || parsed.designer_flag  === 'true';
const price_shopping = parsed.price_shopping === true || parsed.price_shopping === 'true';
const is_custom      = parsed.is_custom      === true || parsed.is_custom      === 'true';

return [{ json: {
  path:                        'consumer',
  subject:                     emailData.subject           || '',
  from_name:                   emailData.from_name         || '',
  from_email:                  emailData.from_email        || '',
  detected_language:           emailData.detected_language || 'en',
  original_body:               emailData.original_body     || '',
  sender_name:                 parsed.sender_name          || emailData.from_name  || '',
  sender_email:                parsed.sender_email         || emailData.from_email || '',
  sender_phone:                parsed.sender_phone         || '',
  product_requested:           parsed.product_category     || '',
  purchase_intent_signal:      parsed.purchase_intent_signal  || 'no_signal',
  extracted_city:              parsed.extracted_city           || '',
  extracted_district:          parsed.extracted_district       || '',
  location_signal:             '',
  product_fit_signal:          parsed.product_fit_signal       || 'similar',
  buyer_urgency_signal:        parsed.buyer_urgency_signal     || 'normal',
  designer_flag,
  source_channel_signal,
  contact_completeness_signal,
  is_custom,
  price_shopping,
  fields_inferred
} }];

const item = $input.first().json;
let raw = item.choices?.[0]?.message?.content ?? '';
if (typeof raw !== 'string') { return [{ json: { parse_error: true, raw_output: raw } }]; }
raw = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/\s*```$/, '');
let parsed;
try { parsed = JSON.parse(raw); }
catch (e) { return [{ json: { parse_error: true, raw_output: raw } }]; }

const emailData = $('Parse Original Body').first()?.json || {};

// ── RELATIONSHIP SOURCE ───────────────────────────────────────
// Decided by the LLM (per V5 doc §5.6). Validate the key, fall back to unknown_inbound.
const validRelationship = ['partner_referral', 'trade_show', 'outbound_pursuit', 'unknown_inbound'];
const relationship_source_signal = validRelationship.includes(parsed.relationship_source_signal)
  ? parsed.relationship_source_signal
  : 'unknown_inbound';

// ── LEGITIMACY GUARD ──────────────────────────────────────────
// full_identity / name_address_only REQUIRE a proper business name.
// The LLM sometimes picks these even when company_name is empty —
// enforce the rule deterministically here.
let business_legitimacy_signal = parsed.business_legitimacy_signal || 'no_identity';
const hasCompanyName = !!(parsed.company_name && parsed.company_name.trim() !== '');

if (!hasCompanyName && (business_legitimacy_signal === 'full_identity' || business_legitimacy_signal === 'name_address_only')) {
  const hasAnyContact = !!(parsed.sender_email || parsed.sender_phone || emailData.from_email);
  business_legitimacy_signal = hasAnyContact ? 'unverified_claim' : 'no_identity';
}

// ── CONTACT COMPLETENESS ──────────────────────────────────────
const hasName  = !!(parsed.sender_name  || emailData.from_name);
const hasEmail = !!(parsed.sender_email || emailData.from_email);
const hasPhone = !!(parsed.sender_phone);
const contactCount = [hasName, hasEmail, hasPhone].filter(Boolean).length;
const contact_completeness_signal =
  contactCount >= 3 ? 'full_contact'  :
  contactCount === 2 ? 'two_of_three' :
  contactCount === 1 ? 'minimal'      :
  'no_contact';

// ── FIELDS INFERRED ───────────────────────────────────────────
// Count from absence — disqualifying signals are stated, not inferred.
const fields_inferred = [
  (!parsed.wholesale_intent_signal || parsed.wholesale_intent_signal === '') ? 1 : 0,
  (!business_legitimacy_signal     || business_legitimacy_signal     === '') ? 1 : 0,
  (!parsed.order_volume_signal     || parsed.order_volume_signal     === '') ? 1 : 0,
  (!parsed.product_range_signal    || parsed.product_range_signal    === '') ? 1 : 0,
  (relationship_source_signal === 'unknown_inbound')                          ? 1 : 0,
  (parsed.store_count === null || parsed.store_count === undefined)           ? 1 : 0,
].reduce((a, b) => a + b, 0);

// ── BOOLEANS ─────────────────────────────────────────────────
const price_shopping = parsed.price_shopping === true || parsed.price_shopping === 'true';

// ── STORE COUNT ───────────────────────────────────────────────
const store_count = (parsed.store_count !== null && parsed.store_count !== undefined && !isNaN(Number(parsed.store_count)))
  ? parseInt(parsed.store_count, 10)
  : null;

return [{ json: {
  path:                        'retail',
  subject:                     emailData.subject           || '',
  from_name:                   emailData.from_name         || '',
  from_email:                  emailData.from_email        || '',
  detected_language:           emailData.detected_language || 'en',
  original_body:               emailData.original_body     || '',
  sender_name:                 parsed.sender_name          || emailData.from_name  || '',
  sender_email:                parsed.sender_email         || emailData.from_email || '',
  sender_phone:                parsed.sender_phone         || '',
  company_name:                parsed.company_name         || '',
  store_count,
  extracted_city:              parsed.extracted_city       || '',
  extracted_district:          parsed.extracted_district   || '',
  location_signal:             '',
  wholesale_intent_signal:     parsed.wholesale_intent_signal     || 'no_b2b_signal',
  business_legitimacy_signal:  business_legitimacy_signal,
  order_volume_signal:         parsed.order_volume_signal         || 'no_volume_signal',
  product_range_signal:        parsed.product_range_signal        || 'general_with_furniture',
  relationship_source_signal,
  contact_completeness_signal,
  price_shopping,
  fields_inferred
} }];

const item = $input.first().json;
return [{ json: {
  ...item,
  team_size:          item.team_size ? parseInt(item.team_size, 10) : null,
  store_count:        item.store_count ? parseInt(item.store_count, 10) : null,
  stated_revenue_aud: item.stated_revenue_aud ? parseInt(item.stated_revenue_aud, 10) : null,
  fields_inferred:    item.fields_inferred ? parseInt(item.fields_inferred, 10) : 0,
  price_shopping:     item.price_shopping === 'true' || item.price_shopping === true,
  cannot_influence:   item.cannot_influence_decision === 'true' || item.cannot_influence_decision === true,
  created_at:         new Date().toISOString()
} }];

